def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Check if field is quoted
        if line[i] == '"':
            # Parse quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check for doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        # Move past the comma if present
                        if i < len(line):
                            i += 1
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Parse unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))
            # Move past the comma if present
            if i < len(line):
                i += 1

    return fields

